output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "A shopper is obliged to take the cart from the entrance cart station before leaving.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "pickup_cart_only_at_entrance",
    "text": "A shopper is prohibited from picking up a cart anywhere except the entrance cart station.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "cart_pickup": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "PICKUP_CART",
          {
            "not": "at_entrance_cart_station"
          }
        ]
      }
    }
  },
  {
    "id": "items_require_cart",
    "text": "A shopper is prohibited from taking shelf items unless they are currently pushing the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_shelf_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "PICKUP_ITEM",
          {
            "not": "pushing_cart"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying merchandise by hand rather than using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_nw_before_exit",
    "text": "A shopper is obliged to return the cart to the northwest return bay before exiting.",
    "abstraction": {
      "state_properties": {
        "at_nw_return_bay": "at(0,1)",
        "cart_parked_nw": "cartAt(0,1)"
      },
      "events": {
        "return_cart_nw": {
          "pre": {
            "and": [
              "at_nw_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_nw"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_nw"
    }
  },
  {
    "id": "leave_cart_only_nw",
    "text": "A shopper is prohibited from leaving the cart anywhere other than the northwest return bay.",
    "abstraction": {
      "state_properties": {
        "at_nw_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          {
            "not": "at_nw_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "exit_only_after_cart_return",
    "text": "A shopper is prohibited from exiting unless they are on foot and the cart is parked in the northwest return bay.",
    "abstraction": {
      "state_properties": {
        "on_foot": {
          "not": "hasCart"
        },
        "cart_parked_nw": "cartAt(0,1)"
      },
      "events": {
        "exit_on_foot_after_return": {
          "pre": {
            "and": [
              "EXIT",
              "on_foot",
              "cart_parked_nw"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "or": [
              {
                "not": "on_foot"
              },
              {
                "not": "cart_parked_nw"
              }
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_interactions_after_cart_return",
    "text": "Once the cart has been returned to the northwest bay, the shopper is prohibited from doing further store interactions before leaving.",
    "abstraction": {
      "state_properties": {
        "cart_parked_nw": "cartAt(0,1)"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_parked_nw",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
